import{DesignSystemManager as s}from"../../d-d-d/lib/DesignSystemManager.js";import{ShadcnTokens as n,ShadcnFonts as e}from"./ShadcnTokens.js";import{ShadcnDDDMap as t}from"./ShadcnDDDMap.js";import{ShadcnIcons as a}from"./ShadcnIcons.js";export const SHADCN_SYSTEM="shadcn";export function registerShadcnDesignSystem(d=s){return d&&!d.systems.shadcn&&d.addDesignSystem({name:"shadcn",extends:"ddd",styles:[n,t],fonts:e,icons:a}),d}export function activateShadcnDesignSystem(n=s){return registerShadcnDesignSystem(n),n&&"shadcn"!==n.active&&(n.active="shadcn"),n}